.collection-header-module div.coll_header_modules div.coll_header_modules_content li{
   width: 304px;
}
.collection-header-module div.coll_header_modules div.coll_header_modules_content li a.wort.ng-sprite-holder,
.collection-header-module div.coll_header_modules div.coll_header_modules_content li a.ng-sprite-holder,
.collection-header-module div.coll_header_modules div.coll_header_modules_content li {
   margin: 0!important;
   width: 30% !important;
   transition: 1s;
   display: flex;
   flex-direction: row;
   position: relative;
}
.collection-header-module div.coll_header_modules div.coll_header_modules_content li span.ng-sprite-content-link {
   transition: 1s;
   display: block;
   margin: 8px 0 8px 0;
   position: absolute;
   right: -95%;
   transition: 1s;
   top: 10px;
   width: 10px;
   height: auto;
   transition: 1s;
   color: #666666;
   pointer-events: none;
   margin-top: 3px;
   margin-left: 8px;
}
.collection-header-module div.coll_header_modules div.coll_header_modules_content li span.ng-sprite-content {
background:linear-gradient(hhtopright3, #333, #999); 
color: #fff; 
margin-left: 9px; 
transition: 1s; 
}
.collection-header-module div.coll_header_modules div.coll_header_modules_content li a.wort.ng-sprite-holder

 a.ng-sprite-holdershown{
