.collection-header-module div.coll_header_modules div.coll_header_modules_content a.ng-sprite-holder {
   display: block;
   position: absolute;
   left: -150%; /*changed from -100% fixed issue*/
   width: 150%;
   listening: 0.4s; z-index: 100;
}

